Here is the commit message:
perf c2c: Display proper cpu count in nodes column

There's wrong bitmap considered when checking for cpu count of specific
node.

We do the needed computation for 'set' variable, but at the end we use
the 'c2c_he->cpuset' weight, which shows misleading numbers.

Fixes: 1e181b92a2da ("perf c2c report: Add 'node' sort key")
Reported-by: Joe Mario <jmario@redhat.com>
Signed-off-by: Jiri Olsa <jolsa@kernel.org>
Cc: Alexander Shishkin <alexander.shishkin@linux.intel.com>
Cc: Michael Petlan <mpetlan@redhat.com>
Cc: Namhyung Kim <namhyung@kernel.org>
Cc: Peter Zijlstra <peterz@infradead.org>
Link: http://lore.kernel.org/lkml/20190820140219.28338-1-jolsa@kernel.org
Signed-off-by: Arnaldo Carvalho de Melo <acme@redhat.com>

Here is the root cause:
The bug was caused by using the wrong bitmap (`c2c_he->cpuset`) to calculate the CPU count for a specific node, leading to misleading numbers in the nodes column. The correct bitmap (`set`) was not utilized, which resulted in inaccurate reporting of CPU counts in the `perf c2c` output.

Here is the patch:

 static int
 node_entry(struct perf_hpp_fmt *fmt __maybe_unused, struct perf_hpp *hpp,
 	   struct hist_entry *he)
 {
 	struct c2c_hist_entry *c2c_he;
 	bool first = true;
 	int node;
 	int ret = 0;

 	c2c_he = container_of(he, struct c2c_hist_entry, he);

 	for (node = 0; node < c2c.nodes_cnt; node++) {
 		DECLARE_BITMAP(set, c2c.cpus_cnt);

 		bitmap_zero(set, c2c.cpus_cnt);
 		bitmap_and(set, c2c_he->cpuset, c2c.nodes[node], c2c.cpus_cnt);

 		if (!bitmap_weight(set, c2c.cpus_cnt)) {
 			if (c2c.node_info == 1) {
 				ret = scnprintf(hpp->buf, hpp->size, "%21s", " ");
 				advance_hpp(hpp, ret);
 			}
 			continue;
 		}

 		if (!first) {
 			ret = scnprintf(hpp->buf, hpp->size, " ");
 			advance_hpp(hpp, ret);
 		}

 		switch (c2c.node_info) {
 		case 0:
 			ret = scnprintf(hpp->buf, hpp->size, "%2d", node);
 			advance_hpp(hpp, ret);
 			break;
 		case 1:
 		{
-			int num = bitmap_weight(c2c_he->cpuset, c2c.cpus_cnt);
+			int num = bitmap_weight(set, c2c.cpus_cnt);
 			struct c2c_stats *stats = &c2c_he->node_stats[node];

 			ret = scnprintf(hpp->buf, hpp->size, "%2d{%2d ", node, num);
 			advance_hpp(hpp, ret);

 		#define DISPLAY_HITM(__h)						\
 			if (c2c_he->stats.__h> 0) {					\
 				ret = scnprintf(hpp->buf, hpp->size, "%5.1f%% ",	\
 						percent(stats->__h, c2c_he->stats.__h));\
 			} else {							\
 				ret = scnprintf(hpp->buf, hpp->size, "%6s ", "n/a");	\
 			}

 			switch (c2c.display) {
 			case DISPLAY_RMT:
 				DISPLAY_HITM(rmt_hitm);
 				break;
 			case DISPLAY_LCL:
 				DISPLAY_HITM(lcl_hitm);
 				break;
 			case DISPLAY_TOT:
 				DISPLAY_HITM(tot_hitm);
 			default:
 				break;
 			}

 		#undef DISPLAY_HITM

 			advance_hpp(hpp, ret);

 			if (c2c_he->stats.store > 0) {
 				ret = scnprintf(hpp->buf, hpp->size, "%5.1f%%}",
 						percent(stats->store, c2c_he->stats.store));
 			} else {
 				ret = scnprintf(hpp->buf, hpp->size, "%6s}", "n/a");
 			}

 			advance_hpp(hpp, ret);
 			break;
 		}
 		case 2:
 			ret = scnprintf(hpp->buf, hpp->size, "%2d{", node);
 			advance_hpp(hpp, ret);

 			ret = bitmap_scnprintf(set, c2c.cpus_cnt, hpp->buf, hpp->size);
 			advance_hpp(hpp, ret);

 			ret = scnprintf(hpp->buf, hpp->size, "}");
 			advance_hpp(hpp, ret);
 			break;
 		default:
 			break;
 		}

 		first = false;
 	}

 	return 0;
 }



